function getInitial(){try{const v=JSON.parse(localStorage.getItem(STORE));if(v&&Array.isArray(v.sessions)&&Array.isArray(v.exercises)){const migrated=normalizeLegacyBackup(v).backup;return {...migrated,routines:Array.isArray(migrated.routines)?migrated.routines:[],bodyWeightHistory:Array.isArray(migrated.bodyWeightHistory)?migrated.bodyWeightHistory:[],settings:{name:'Athlete',height:'',sound:false,...migrated.settings}}}}catch(e){}return {sessions:[],exercises:defaultExercises,routines:[],bodyWeightHistory:[],settings:{name:'Athlete',height:'',sound:false},draft:null};}
let db=getInitial(),page='dashboard',draft=null,routineEditor=null,libraryFilter='All',historyFilter='Both',historyMonth=`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`,historyDayFilter='',expandedSession=null,toastTimer=null,reportFilter={month:String(new Date().getMonth()+1),year:String(new Date().getFullYear()),location:'Both'};
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
