const minsBetween=(date,start,end)=>{if(!start||!end)return 0;const a=new Date(`${date}T${start}`),b=new Date(`${date}T${end}`);let n=(b-a)/60000;if(n<0)n+=1440;return Math.max(0,Math.round(n))};
const durationLabel=m=>{const totalSeconds=Math.max(0,Math.round(safe(m)*60));if(totalSeconds===0)return '0 min';const h=Math.floor(totalSeconds/3600),remaining=totalSeconds%3600,minutes=Math.floor(remaining/60),seconds=remaining%60;if(h)return `${h}h ${minutes}m${seconds?` ${seconds}s`:''}`;if(minutes)return seconds?`${minutes}m ${seconds}s`:`${minutes} min`;return `${seconds} sec`};
const minsOf=s=>{const stored=s?.durationMinutes;if(stored!==undefined&&stored!==null&&stored!==''&&Number.isFinite(Number(stored))&&Number(stored)>=0)return Math.max(0,Number(stored));return minsBetween(s?.date,s?.startTime,s?.endTime)};
const latestWeight=()=>{const entries=[];db.bodyWeightHistory.forEach((x,i)=>entries.push({date:x.date,weight:safe(x.weight),recordedAt:x.recordedAt||`${x.date}T00:00:00`,order:i}));db.sessions.forEach((s,i)=>{if(s.bodyWeight)entries.push({date:s.date,weight:safe(s.bodyWeight),recordedAt:s.createdAt||`${s.date}T${s.startTime||'00:00'}:00`,order:db.bodyWeightHistory.length+i+1})});entries.sort((a,b)=>b.date.localeCompare(a.date)||String(b.recordedAt).localeCompare(String(a.recordedAt))||b.order-a.order);return entries.find(x=>x.weight>0)?.weight||''};
let apiReady=false,serverSaveTimer=null,serverSaveChain=Promise.resolve(),serverWarningShown=false,reconnectTimer=null,syncFinished=false,localChangesDuringDisconnect=false;
function persist(){
 try{localStorage.setItem(STORE,JSON.stringify(db));}catch(e){showToast('Could not update the browser cache. Check storage space and keep a backup.');}
 if(apiReady)queueServerSave();
 else if(syncFinished)localChangesDuringDisconnect=true;
}
function scheduleServerRetry(){
 if(reconnectTimer||!syncFinished)return;
 reconnectTimer=setTimeout(()=>{reconnectTimer=null;syncServerState(true)},5000);
}
function queueServerSave(){
 clearTimeout(serverSaveTimer);
 serverSaveTimer=setTimeout(()=>{
  const snapshot=JSON.stringify(db);
  serverSaveChain=serverSaveChain.catch(()=>{}).then(async()=>{
   const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});
   if(!response.ok){let detail='';try{detail=(await response.json()).error||''}catch(e){}throw new Error(detail||'Save rejected by the local database.');}
   apiReady=true;syncFinished=true;localChangesDuringDisconnect=false;serverWarningShown=false;
   if(reconnectTimer){clearTimeout(reconnectTimer);reconnectTimer=null;}
  }).catch(error=>{
   apiReady=false;localChangesDuringDisconnect=true;
   if(!serverWarningShown){serverWarningShown=true;showToast('SQLite save failed. Your browser cache is preserved; retrying the database connection.');}
   console.error('FORMA database save failed:',error);
   scheduleServerRetry();
  });
 },180);
}
async function putStateToServer(state){
 const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});
 if(!response.ok){let detail='';try{detail=(await response.json()).error||''}catch(e){}throw new Error(detail||'Could not initialize the SQLite database.');}
}
async function syncServerState(isRetry=false){
 // Automatic reconnects happen in the background. Keep the rendered page stable
 // unless the data genuinely changed, otherwise each retry makes the screen flash.
 const stateBeforeSync=JSON.stringify(db);
 try{
  const response=await fetch('/api/state',{cache:'no-store'});
  if(!response.ok)throw new Error('The local database server did not respond.');
  const saved=await response.json();
  const uploadLocal=Boolean(!saved.initialized||(isRetry&&localChangesDuringDisconnect));
  if(saved.initialized&&!uploadLocal){
   if(!saved.state||!Array.isArray(saved.state.sessions)||!Array.isArray(saved.state.exercises))throw new Error('The saved SQLite state is malformed.');
   saved.state.routines=Array.isArray(saved.state.routines)?saved.state.routines:[];const savedIssue=backupValidationError(saved.state);if(savedIssue)throw new Error('Saved SQLite data failed validation: '+savedIssue);
   db=saved.state;
   if(!Array.isArray(db.bodyWeightHistory))db.bodyWeightHistory=[];
   db.settings={name:'Athlete',height:'',sound:false,...(db.settings||{})};
   if(!Object.prototype.hasOwnProperty.call(db,'draft'))db.draft=null;
   draft=db.draft&&Array.isArray(db.draft.exercises)?db.draft:null;
   try{localStorage.setItem(STORE,JSON.stringify(db));}catch(e){}
  }
  if(uploadLocal)await putStateToServer(db);
  apiReady=true;syncFinished=true;localChangesDuringDisconnect=false;serverWarningShown=false;
  if(reconnectTimer){clearTimeout(reconnectTimer);reconnectTimer=null;}
  document.body.classList.remove('loading');
  if(!isRetry||stateBeforeSync!==JSON.stringify(db))render();
 }catch(error){
  document.body.classList.remove('loading');
  apiReady=false;syncFinished=true;
  // The cached page was rendered before the first sync. On connection errors,
  // only update connection state and schedule a retry; do not rebuild the UI.
  console.error('FORMA could not connect to SQLite:',error);
  if(!serverWarningShown){serverWarningShown=true;showToast('SQLite server unavailable. Your browser cache is preserved; FORMA will retry connecting.');}
  scheduleServerRetry();
 }
}
function showToast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function pageInfo(p){return ({dashboard:['YOUR TRAINING OVERVIEW','Dashboard'],log:['MAKE TODAY COUNT','Log a workout'],schedule:['YOUR WEEK, YOUR WAY','Workout schedule'],history:['YOUR TRAINING JOURNAL','Workout history'],library:['BUILT FOR YOUR ROUTINE','Exercise library'],progress:['THE BIGGER PICTURE','Progress & stats'],reports:['YOUR DATA, BEAUTIFULLY SUMMARIZED','Reports & exports'],settings:['YOUR SPACE, YOUR RULES','Settings & backup']})[p]||['FORMA','Dashboard']}
function navigate(p,loc){if(!p)return;page=p;if(p==='log'&&!draft){draft=makeDraft(loc||'Home');persistDraft();}if(p==='log'&&loc&&draft&&draft.location!==loc&&draft.exercises.length===0&&!draft.editingId){draft.location=loc;persistDraft();}render();window.scrollTo({top:0,behavior:'smooth'});}
function makeDraft(location='Home',source=null){return {location,date:todayISO(),startTime:localTime(),endTime:'',bodyWeight:latestWeight(),notes:'',title:'',exercises:[],...(source?JSON.parse(JSON.stringify(source)): {}),id:uid(),dirty:false}}
function hasDraftWork(){return Boolean(draft&&(draft.dirty||draft.editingId||(draft.exercises||[]).length||(draft.notes||'').trim()||(draft.title||'').trim()||draft.endTime||draft.date!==todayISO()||String(draft.bodyWeight??'')!==String(latestWeight()??'')));}
