function openWeighIn(){ $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="weigh-title"><div class="modal-head"><h2 id="weigh-title">Record body weight</h2><button class="modal-close" data-action="close-modal">×</button></div><form id="weigh-form"><div class="form-grid" style="grid-template-columns:1fr 1fr"><div class="field"><label for="weigh-date">Date</label><input id="weigh-date" name="date" type="date" value="${todayISO()}" required></div><div class="field"><label for="weigh-value">Weight (kg)</label><input id="weigh-value" name="weight" type="number" min="1" max="500" step="0.1" required value="${esc(latestWeight())}" placeholder="e.g. 68.5"></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save measurement</button></div></form></section></div>`}
