function clearAll(){if(!confirm('Delete all workout sessions, custom routines, custom exercises, and body-weight history? This cannot be undone. Export a backup first if you need these records.'))return;db={sessions:[],exercises:defaultExercises.map(e=>({...e})),routines:[],bodyWeightHistory:[],settings:{name:db.settings.name||'Athlete',height:db.settings.height||'',sound:!!db.settings.sound},draft:null};draft=null;persist();page='dashboard';render();showToast('Workout data cleared.')}
function normalizeLegacyBackup(source){
 // Earlier FORMA versions allowed users to type a load range such as "5-7".
 // The current app stores one numeric load per set, so preserve a range as a note
 // instead of inventing a midpoint or rejecting otherwise valid historical data.
 let obj;
 try{obj=JSON.parse(JSON.stringify(source));}catch(e){return {backup:source,migratedWeightRanges:0};}
 let migratedWeightRanges=0;
 const normalizeSet=st=>{
  if(!st||typeof st!=='object'||Array.isArray(st)||typeof st.weight!=='string')return;
  const raw=st.weight.trim();
  if(!raw||Number.isFinite(Number(raw)))return;
  const range=raw.match(/^(\d+(?:\.\d+)?)\s*(?:-|–|—|to)\s*(\d+(?:\.\d+)?)(?:\s*kg)?$/i);
  if(range){
   st.weight='';
   const label=`Original recorded load range: ${raw.replace(/\s*kg$/i,'')} kg`;
   const existing=typeof st.note==='string'?st.note.trim():'';
   const separator=existing?' · ':'';
   const room=Math.max(0,1000-label.length-separator.length);
   st.note=(existing.slice(0,room)+separator+label).slice(0,1000);
   migratedWeightRanges++;
   return;
  }
  const single=raw.match(/^(\d+(?:\.\d+)?)\s*kg$/i);
  if(single)st.weight=single[1];
 };
 const visitExercises=items=>{if(!Array.isArray(items))return;for(const exercise of items){if(!exercise||typeof exercise!=='object')continue;if(Array.isArray(exercise.sets))exercise.sets.forEach(normalizeSet);}};
 if(Array.isArray(obj?.sessions))for(const session of obj.sessions)visitExercises(session?.exercises);
 visitExercises(obj?.draft?.exercises);
 if(!Array.isArray(obj.routines))obj.routines=[];
 return {backup:obj,migratedWeightRanges};
}
