 if(settings.name!=null&&(typeof settings.name!=='string'||settings.name.trim().length>50))return 'The profile name is invalid.';
 if(settings.height!=null&&settings.height!==''&&(typeof settings.height==='boolean'||!Number.isFinite(Number(settings.height))||Number(settings.height)<=0||Number(settings.height)>300))return 'The profile height is invalid.';
