    if(st.reps!=null&&st.reps!==''&&(typeof st.reps==='boolean'||!Number.isFinite(Number(st.reps))||!Number.isInteger(Number(st.reps))||Number(st.reps)<1||Number(st.reps)>10000))return 'A workout contains an invalid rep count.';
    if(st.value!=null&&st.value!==''&&(typeof st.value==='boolean'||!Number.isFinite(Number(st.value))||Number(st.value)<=0||Number(st.value)>1000000))return 'A workout contains an invalid measurement.';
    if(st.note!=null&&typeof st.note!=='string')return 'A workout contains an invalid set note.';
