 for(const x of obj.bodyWeightHistory||[])if(!x||typeof x!=='object'||Array.isArray(x)||!isISODate(x.date)||typeof x.weight==='boolean'||!Number.isFinite(Number(x.weight))||Number(x.weight)<=0||Number(x.weight)>500||x.recordedAt!=null&&typeof x.recordedAt!=='string')return 'The body-weight history contains invalid data.';
